import React from 'react';
import { Routes, Route } from 'react-router-dom';

// Pages & Components
import Home from '../pages/Home/Home';
import Login from '../pages/Login/Login';
import Register from '../pages/Register/Register';
import Dashboard from '../pages/Dashboard/Dashboard';
import AdminDashboard from '../pages/Dashboard/AdminDashboard';
import TrackingSection from '../components/tracking/TrackingSection';

// Aapka Naya Truck Booking Page
import TruckBookingPage from '../components/Truckpage/TruckBookingPage'; 

const AppRoutes = () => {
  return (
    <Routes>
      {/* Home Route */}
      <Route path="/" element={<Home />} />

      {/* Booking & Tracking */}
      <Route path="/track" element={<TrackingSection />} />
      {/* Humne App.js mein path "/book-truck" rakha hai, toh yahan bhi wahi use karenge */}
      <Route path="/book-truck" element={<TruckBookingPage />} />

      {/* Auth Routes */}
      <Route path="/login" element={<Login />} />
      <Route path="/register" element={<Register />} />

      {/* Dashboards */}
      <Route path="/dashboard" element={<Dashboard />} />
      <Route path="/user-dashboard" element={<Dashboard />} />
      <Route path="/admin-dashboard" element={<AdminDashboard />} />
      <Route path="/book-truck" element={<TruckBookingPage />} />   
      

      {/* 404 Fallback */}
      <Route path="*" element={<div style={{padding: '50px', textAlign: 'center'}}><h2>404 - Page Not Found</h2></div>} />
    </Routes>
  );
};

export default AppRoutes;
